 OUT.mkdir(parents=True,exist_ok=True);jar=Path(os.environ['SIMPLENLG_JAR']);classes=OUT/'classes';classes.mkdir(exist_ok=True);comp=subprocess.run(['javac','--release','17','-cp',str(jar),'-d',str(classes),str(P/'LanguageProbe.java')],text=True,capture_output=True);assert comp.returncode==0,comp.stderr;run=subprocess.run(['java','-cp',f'{classes}:{jar}','LanguageProbe'],text=True,capture_output=True);assert run.returncode==0,run.stderr;outputs=dict(line.split('\t',1) for line in run.stdout.strip().splitlines())
